def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 52.0)
        return min(budget, 28.0)

    total_alive = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < total_alive

    highest_prev_bid = 0.0
    aggressive_count = 0
    desperate_opp = 0
    for opp in alive_opponents:
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 2:
            desperate_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            if bid > highest_prev_bid:
                highest_prev_bid = bid
            if bid >= DAILY_SALARY * 0.75:
                aggressive_count += 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if scarcity:
        urgency += 1
    if desperate_opp >= max(1, len(alive_opponents) // 2):
        urgency += 1
    if aggressive_count > 0:
        urgency += 1

    if urgency >= 6:
        target = max(63.0, highest_prev_bid + 2.0)
    elif urgency >= 4:
        target = max(52.0, highest_prev_bid + 1.0 if highest_prev_bid > 0 else 52.0)
    elif urgency >= 2:
        if highest_prev_bid >= 56.0:
            target = 34.0
        else:
            target = max(38.0, highest_prev_bid + 1.0 if highest_prev_bid > 0 else 38.0)
    else:
        if expected_units >= total_alive:
            target = 18.0
        elif highest_prev_bid >= 56.0:
            target = 22.0
        else:
            target = 28.0

    if budget < target:
        if hp <= 2 or no_water_days >= 1:
            return max(0.0, budget)
        return max(0.0, min(budget, target * 0.7))

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', (MIN_SUPPLY + MAX_SUPPLY) / 2.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, bid to meet requirement but don't overspend.
    if not alive_opponents:
        target = min(budget, DAILY_SALARY * 0.55)
        return max(0.0, target)

    # Read only yesterday's immediate behavior.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Base bid: aim around a fraction of daily salary to avoid unnecessary price.
    # If my hp is low or I've been without water, increase urgency.
    urgency = 0.0
    if hp <= 2:
        urgency += 0.35
    elif hp <= 4:
        urgency += 0.15

    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days == 1:
        urgency += 0.10

    # Supply pressure: if supply is tight, bid more.
    # supply in [15,25], map to [0,1]
    supply_tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_tightness = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_tightness = max(0.0, min(1.0, supply_tightness))

    base_fraction = 0.55 + urgency + 0.15 * supply_tightness

    # If an opponent previously bid extremely high, we counter modestly to avoid losing allocation.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Thresholds relative to salary.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # They were likely fighting for survival; raise bid but cap by budget.
            counter_fraction = 0.70 + 0.20 * supply_tightness
            if hp <= 2:
                counter_fraction = 0.90
            target = min(budget, DAILY_SALARY * counter_fraction)
            return max(0.0, target)
        elif highest_prev_bid >= DAILY_SALARY * 0.60:
            # Mild counter.
            counter_fraction = base_fraction + 0.10
            target = min(budget, DAILY_SALARY * counter_fraction)
            return max(0.0, target)

    # Default: bid based on urgency and supply tightness.
    target = min(budget, DAILY_SALARY * base_fraction)

    # Ensure we don't bid trivially low when supply is near requirement.
    # If supply is close to WATER_REQ, increase slightly.
    if supply <= float(WATER_REQ) + 1.0:
        target = min(budget, max(target, DAILY_SALARY * 0.65))

    return max(0.0, target)
